css:
/* V38: compact tools in the real visible forest stage (not behind the stage). */
#forst-stage #fs-top-tools{position:absolute;top:8.1%;right:3.3%;z-index:36;display:flex;align-items:center;justify-content:flex-end;gap:4px;pointer-events:auto;max-width:65%;}
#forst-stage #fs-top-tools>button{position:relative!important;inset:auto!important;right:auto!important;top:auto!important;opacity:1!important;visibility:visible!important;display:flex!important;flex-direction:column;align-items:center;justify-content:center;flex:none!important;width:45px!important;height:45px!important;min-width:45px!important;min-height:45px!important;padding:3px!important;margin:0!important;background:linear-gradient(160deg,#352a18f2,#07150ff5)!important;color:#fce7bd!important;border:2px ridge #c89b50!important;border-radius:6px!important;box-shadow:0 2px 8px #000b,inset 0 0 0 1px #775127!important;font:700 11px/1.02 Georgia,serif!important;text-shadow:0 1px 2px #000!important;cursor:pointer;touch-action:manipulation;}
#forst-stage #fs-top-tools>button>span{display:block!important;font:22px/1 Georgia,serif!important;min-height:22px;}
#forst-stage #fs-top-tools>button:active{transform:translateY(1px);filter:brightness(1.15)}
#forst-stage #fs-top-tools>button:focus-visible{outline:3px solid #fff0b4!important;outline-offset:2px!important}
#forst-stage #fs-top-tools #fs-3d[aria-pressed="true"]{background:linear-gradient(150deg,#315e46,#112317)!important;box-shadow:0 0 0 1px #b3a06a,inset 0 0 6px #70c68c33!important;}
#forst-stage #fs-3d-menu{position:absolute;top:12%;right:3.3%;width:min(290px,82vw);max-height:68dvh;overflow:auto;z-index:40;background:linear-gradient(135deg,#f9e8c8,#eac999);border:3px ridge #916936;border-radius:8px;padding:13px 14px;box-shadow:0 9px 24px #000c;color:#261b0e;font:14px/1.4 Georgia,serif;}
#forst-stage #fs-3d-menu[hidden]{display:none!important;}
#forst-stage #fs-3d-menu h3{font:700 19px/1.2 Georgia,serif;margin:0 24px 8px 0;color:#33200f;}
#forst-stage #fs-3d-menu p{margin:8px 0;font:13px/1.35 Georgia,serif;color:#51371c;}
#forst-stage #fs-3d-menu .fs-modes{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:10px 0;}
#forst-stage #fs-3d-menu button{background:linear-gradient(#264535,#071812);color:#fce5bb;border:1px solid #ae8144;border-radius:5px;min-height:42px;padding:7px;cursor:pointer;font:700 13px Georgia,serif;}
#forst-stage #fs-3d-menu button[aria-pressed="true"]{background:#7d5529;outline:2px solid #ecd091;outline-offset:-3px;}
#forst-stage #fs-3d-menu .fs-close{position:absolute;right:7px;top:7px;min-height:31px;width:33px;font:22px/1 Georgia,serif;}
#forst-stage #fs-3d-menu #fs-tilt{display:block;width:100%;margin:5px 0;}
#forst-stage.fs-depth-on #fs-banner-img{transform:translate3d(var(--fs-dx,0px),var(--fs-dy,0px),0) scale(1.10)!important;transition:transform .14s ease-out;will-change:transform;}
#forst-stage.fs-depth-on #fs-beast-img{transform:translate3d(calc(var(--fs-dx,0px)*.6),calc(var(--fs-dy,0px)*.6),0) scale(1.035)!important;transition:transform .14s ease-out;will-change:transform;}
@media(max-width:350px){#forst-stage #fs-top-tools{right:2%;gap:3px;}#forst-stage #fs-top-tools>button{width:40px!important;min-width:40px!important;height:43px!important;min-height:43px!important;font-size:10px!important;}#forst-stage #fs-top-tools>button>span{font-size:19px!important;}}
@media(prefers-reduced-motion:reduce){#forst-stage.fs-depth-on #fs-banner-img,#forst-stage.fs-depth-on #fs-beast-img{transition:none!important;}}

js:
(()=>{
 'use strict';
 const stage=document.getElementById('forst-stage');
 const zoomBtn=document.getElementById('fs-imgbtn');
 if(!stage||!zoomBtn)return;
 const bar=document.createElement('nav');bar.id='fs-top-tools';bar.setAttribute('aria-label','Musik, 3D und Bild');
 const mp3=document.createElement('button');mp3.id='fs-mp3';mp3.type='button';mp3.title='MP3-Player öffnen';mp3.setAttribute('aria-label','MP3-Player öffnen');mp3.innerHTML='<span aria-hidden="true">♫</span>MP3';
 const depth=document.createElement('button');depth.id='fs-3d';depth.type='button';depth.title='Räumlicher Bildeffekt';depth.setAttribute('aria-label','3D-Einstellungen öffnen');depth.innerHTML='<span aria-hidden="true">◇</span>3D';depth.setAttribute('aria-expanded','false');
 zoomBtn.setAttribute('aria-label','Bild vergrößern');
 bar.append(mp3,depth,zoomBtn);stage.appendChild(bar);
 const menu=document.createElement('section');menu.id='fs-3d-menu';menu.hidden=true;menu.setAttribute('aria-label','Räumlicher Bildeffekt');
 menu.innerHTML='<button class="fs-close" type="button" aria-label="Schließen">×</button><h3>Räumliche Bilder</h3><p>Sanfter Tiefeneindruck durch Bildbewegung. Die Schrift bleibt ruhig.</p><div class="fs-modes"><button type="button" data-depth="aus">Aus</button><button type="button" data-depth="sanft">Sanft</button><button type="button" data-depth="stark">Stark</button></div><button type="button" id="fs-tilt">iPhone-Neigung aktivieren</button><p id="fs-depth-status" role="status">Du kannst das Szenenbild auch mit dem Finger bewegen.</p>';
 stage.appendChild(menu);
 let mode='aus', swiped=false, start=null, tiltEnabled=false;
 const key='forst-visible-depth-v38';
 try{const saved=localStorage.getItem(key);if(['aus','sanft','stark'].includes(saved))mode=saved;}catch(e){}
 const img=document.getElementById('fs-banner-img'),beast=document.getElementById('fs-beast-img'),scene=document.getElementById('fs-banner');
 function message(v){const p=document.getElementById('fs-depth-status');if(p)p.textContent=v;}
 function max(){return mode==='stark'?13:mode==='sanft'?7:0;}
 function shift(x,y){const k=max();stage.style.setProperty('--fs-dx',Math.max(-k,Math.min(k,x)).toFixed(2)+'px');stage.style.setProperty('--fs-dy',Math.max(-k,Math.min(k,y)).toFixed(2)+'px');}
 function refresh(){stage.classList.toggle('fs-depth-on',mode!=='aus');depth.setAttribute('aria-pressed',String(mode!=='aus'));menu.querySelectorAll('[data-depth]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.depth===mode)));if(mode==='aus')shift(0,0);}
 function setMode(m){if(!['aus','sanft','stark'].includes(m))return;mode=m;try{localStorage.setItem(key,m);}catch(e){}refresh();message(m==='aus'?'3D ist ausgeschaltet.':'Bild mit dem Finger bewegen oder iPhone-Neigung aktivieren.');}
 mp3.onclick=()=>{menu.hidden=true;depth.setAttribute('aria-expanded','false');if(typeof showMusic==='function')showMusic();else if(typeof openPanel==='function')openPanel('music');};
 depth.onclick=()=>{menu.hidden=!menu.hidden;depth.setAttribute('aria-expanded',String(!menu.hidden));};
 menu.querySelector('.fs-close').onclick=()=>{menu.hidden=true;depth.setAttribute('aria-expanded','false');};
 menu.querySelectorAll('[data-depth]').forEach(b=>b.onclick=()=>setMode(b.dataset.depth));
 menu.querySelector('#fs-tilt').onclick=async()=>{
  if(mode==='aus'){message('Zuerst Sanft oder Stark wählen.');return;}
  if(tiltEnabled){message('iPhone-Neigung ist bereits aktiv.');return;}
  if(typeof DeviceOrientationEvent==='undefined'){message('Keine Bewegungssensoren verfügbar; Fingerbewegung funktioniert weiterhin.');return;}
  try{
   if(typeof DeviceOrientationEvent.requestPermission==='function'){
     const response=await DeviceOrientationEvent.requestPermission();
     if(response!=='granted'){message('Sensorzugriff nicht freigegeben. Du kannst das Bild weiterhin mit dem Finger bewegen.');return;}
   }
   window.addEventListener('deviceorientation',e=>{if(mode==='aus'||start)return;const x=(Number(e.gamma)||0)*max()/26,y=((Number(e.beta)||0)-30)*max()/34;shift(x,y);},{passive:true});
   tiltEnabled=true;message('Neigung aktiv. Bewege das iPhone leicht.');
  }catch(e){message('Neigung nicht verfügbar. Fingersteuerung funktioniert weiterhin.');}
 };
 if(scene){
  scene.addEventListener('pointerdown',e=>{if(mode==='aus')return;swiped=false;start={x:e.clientX,y:e.clientY};});
  scene.addEventListener('pointermove',e=>{if(mode==='aus'||!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>6){swiped=true;shift(dx*.4,dy*.4);if(e.cancelable)e.preventDefault();}},{passive:false});
  scene.addEventListener('click',e=>{if(swiped){e.preventDefault();e.stopImmediatePropagation();swiped=false;}},true);
  ['pointerup','pointercancel','pointerleave'].forEach(t=>scene.addEventListener(t,()=>{start=null;}));
 }
 document.addEventListener('pointerdown',e=>{if(!menu.hidden&&!menu.contains(e.target)&&e.target!==depth){menu.hidden=true;depth.setAttribute('aria-expanded','false');}},true);
 refresh();
})();
